"""``urcap.toml`` → ``ps5/`` (Java/Swing OSGi sources) and ``psx/`` (PolyScope X web archive).

Ownership rule — the one thing to know before editing a URCap by hand:

* A file that starts with the ``GENERATED by urcapgen`` marker (and the JSON files listed in
  :data:`ALWAYS_GENERATED`) belongs to the generator. ``urcapgen gen`` rewrites it and deletes
  it when the spec no longer calls for it. Change ``urcap.toml`` instead.
* Every other file under ``ps5/`` and ``psx/`` belongs to you. The generator creates the hook
  files (``<Node>Hooks.java``, ``<node>.hooks.js``) once, with working defaults, and never
  touches them again. Extra classes or scripts you add are left alone (a PS5 class goes in
  the generated package's directory; a PSX script must be loaded by a hooks file).
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from importlib import resources
from pathlib import Path

from . import __version__
from .spec import Field, Node, Spec

MARK = "GENERATED by urcapgen"
ALWAYS_GENERATED = ("contribution.json", "en.json")
RUNTIME = resources.files("urcapgen") / "runtime"


@dataclass
class Out:
    path: str  # relative to the URCap's directory
    text: str
    owned: bool = False  # True: user-owned, written only if absent


# -- small helpers ------------------------------------------------------------------------------


def jstr(s: str) -> str:
    """A Java string literal."""
    out = ['"']
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif ord(ch) < 0x20 or ord(ch) > 0x7E:
            out.append(f"\\u{ord(ch):04x}")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def jnum(x: float | None) -> str:
    return "null" if x is None else f"{float(x)!r}"


def java_default(f: Field) -> str:
    if f.type == "int":
        return f"Integer.valueOf({int(f.default)})"
    if f.type == "float":
        return f"Double.valueOf({float(f.default)!r})"
    if f.type == "bool":
        return "Boolean.TRUE" if f.default else "Boolean.FALSE"
    if f.type == "pose":
        return "new double[] {" + ", ".join(repr(float(v)) for v in f.default) + "}"
    return jstr(str(f.default))


def java_def(f: Field) -> str:
    vals = labels = "null"
    if f.options:
        vals = "new String[] {" + ", ".join(jstr(o["value"]) for o in f.options) + "}"
        labels = "new String[] {" + ", ".join(jstr(o["label"]) for o in f.options) + "}"
    return (
        f"new Form.Def({jstr(f.key)}, {jstr(f.type)}, {jstr(f.label)}, {jstr(f.unit)}, {jstr(f.help)},\n"
        f"                    {jnum(f.min)}, {jnum(f.max)}, {java_default(f)}, {vals}, {labels})"
    )


def runtime_text(name: str, spec: Spec) -> str:
    text = (RUNTIME / name).read_text(encoding="utf-8")
    return text.replace("@@PACKAGE@@", spec.java_package).replace("@@VERSION@@", __version__)


def js_runtime() -> str:
    """How generated JS names its runtime: this urcapgen version's, never another URCap's."""
    return f'self.UrcapgenRuntimes["{__version__}"]'


def js_page_loader(hooks_file: str) -> str:
    """The presenters' loader: runtime first (by a plain tag; it may already be in the page
    from another presenter of this URCap), then this URCap's spec and the node's hooks
    through the runtime's shared once-per-URL loader."""
    return (
        "  const here = (document.currentScript && document.currentScript.src) || location.href;\n"
        "  const url = (name) => new URL(name, here).href;\n"
        "  let ready = null;\n"
        "  const libs = () => ready || (ready = (async () => {\n"
        f"    if (!(self.UrcapgenRuntimes || {{}})[\"{__version__}\"]) {{\n"
        "      const loads = (self.UrcapgenLoads = self.UrcapgenLoads || {});\n"
        '      const src = url("urcapgen-runtime.js");\n'
        "      loads[src] = loads[src] || new Promise((resolve, reject) => {\n"
        '        const s = document.createElement("script");\n'
        "        s.src = src; s.onload = () => resolve(); s.onerror = () => reject(new Error(`could not load ${src}`));\n"
        "        document.head.appendChild(s);\n      });\n"
        "      await loads[src];\n    }\n"
        f"    const U = {js_runtime()};\n"
        '    await U.loadScript(url("spec.js"));\n'
        f'    await U.loadScript(url("{hooks_file}"));\n'
        "    return U;\n"
        "  })());\n"
    )


def initials(spec: Spec) -> str:
    words = [w for w in spec.name.replace("-", " ").split() if w]
    s = "".join(w[0] for w in words[:2]).upper()
    return s or spec.id[:2].upper()


def icon_svg(spec: Spec, text: str) -> str:
    return (
        f"<!-- {MARK} -->\n"
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="48" height="48">'
        '<rect x="2" y="2" width="44" height="44" rx="10" fill="#1f6feb"/>'
        '<text x="24" y="31" font-family="Arial, Helvetica, sans-serif" font-size="18" font-weight="700" '
        f'fill="#ffffff" text-anchor="middle">{text}</text></svg>\n'
    )


def java_header(spec: Spec, what: str) -> str:
    return f"// {MARK} {__version__} from urcap.toml — {what}. Do not edit; change the spec.\npackage {spec.java_package};\n"


# -- PolyScope 5 --------------------------------------------------------------------------------


def ps5_bundle_properties(spec: Spec) -> str:
    desc = spec.description.replace("\n", " ") or spec.name
    lines = [
        f"# {MARK} {__version__} from urcap.toml. Do not edit; change the spec.",
        f"Bundle-SymbolicName={spec.symbolic_name}",
        f"Bundle-Name={spec.name}",
        f"Bundle-Vendor={spec.vendor_name}",
        f"Bundle-Copyright=Copyright (c) {spec.vendor_name}",
        f"Bundle-Version={spec.version}",
        f"Bundle-Activator={spec.java_package}.Activator",
        f"Bundle-Description={desc}",
        "URCapCompatibility-CB3=false",
        "URCapCompatibility-eSeries=true",
        f"compat.floor={spec.ps5_floor}",
    ]
    return "\n".join(lines) + "\n"


def ps5_activator(spec: Spec) -> str:
    imports = {"org.osgi.framework.BundleActivator", "org.osgi.framework.BundleContext"}
    regs = []
    if spec.installation:
        imports.add("com.ur.urcap.api.contribution.installation.swing.SwingInstallationNodeService")
        regs.append(
            f"        context.registerService(SwingInstallationNodeService.class, new {spec.installation.cls}Service(), null);"
        )
    for p in spec.programs:
        imports.add("com.ur.urcap.api.contribution.program.swing.SwingProgramNodeService")
        regs.append(f"        context.registerService(SwingProgramNodeService.class, new {p.cls}Service(), null);")
    if spec.toolbar:
        imports.add("com.ur.urcap.api.contribution.toolbar.swing.SwingToolbarService")
        regs.append("        context.registerService(SwingToolbarService.class, new ToolbarService(), null);")
    if spec.daemon:
        imports.add("com.ur.urcap.api.contribution.DaemonService")
        regs.insert(0, "        context.registerService(DaemonService.class, DAEMON, null);")
    body = "\n".join(regs)
    daemon_field = "    static final Daemon DAEMON = new Daemon();\n\n" if spec.daemon else ""
    return (
        java_header(spec, "registers every node with PolyScope 5")
        + "\n"
        + "".join(f"import {i};\n" for i in sorted(imports))
        + "\npublic class Activator implements BundleActivator {\n"
        + daemon_field
        + "    @Override\n    public void start(BundleContext context) {\n"
        + body
        + "\n    }\n\n    @Override\n    public void stop(BundleContext context) {\n    }\n}\n"
    )


def ps5_spec_class(spec: Spec, n: Node) -> str:
    defs = ",\n            ".join(java_def(f) for f in n.fields)
    after = ""
    if n.allows_children:
        after = (
            "\n    /** The script after the children (template, then the hooks). */\n"
            "    static String scriptAfter(Map<String, ScriptTemplate.Value> v) {\n"
            f"        return {n.cls}Hooks.scriptAfter(v, ScriptTemplate.render(SCRIPT_AFTER, v));\n"
            "    }\n"
        )
    return (
        java_header(spec, f"the {n.kind} node {n.id!r}: its fields and templates")
        + "\nimport java.util.Arrays;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Map;\n\n"
        + f"final class {n.cls}Spec {{\n"
        + f"    static final String TITLE = {jstr(n.title)};\n"
        + f"    static final String DESCRIPTION = {jstr(n.description)};\n"
        + f"    static final String SCRIPT = {jstr(n.script)};\n"
        + f"    static final String SCRIPT_AFTER = {jstr(n.script_after)};\n"
        + f"    static final String LABEL = {jstr(n.label)};\n"
        + "    static final List<Form.Def> FIELDS = Collections.unmodifiableList(Arrays.<Form.Def>asList(\n"
        + (f"            {defs}" if n.fields else "")
        + "));\n\n"
        + f"    private {n.cls}Spec() {{\n    }}\n\n"
        + "    /** The node's script (template, then the hooks): what PolyScope runs. */\n"
        + "    static String script(Map<String, ScriptTemplate.Value> v) {\n"
        + f"        return {n.cls}Hooks.script(v, ScriptTemplate.render(SCRIPT, v));\n"
        + "    }\n"
        + after
        + "\n    /** Why the node is not ready (the spec's limits, then the hooks), or null. */\n"
        + "    static String problem(Map<String, ScriptTemplate.Value> v, String specProblem) {\n"
        + f"        return specProblem != null ? specProblem : {n.cls}Hooks.validate(v);\n"
        + "    }\n}\n"
    )


def ps5_program(spec: Spec, n: Node) -> list[Out]:
    d = spec.java_dir
    c = n.cls
    service = (
        java_header(spec, f"program node {n.id!r}: the service PolyScope 5 asks for it")
        + """
import com.ur.urcap.api.contribution.ViewAPIProvider;
import com.ur.urcap.api.contribution.program.ContributionConfiguration;
import com.ur.urcap.api.contribution.program.CreationContext;
import com.ur.urcap.api.contribution.program.ProgramAPIProvider;
import com.ur.urcap.api.contribution.program.swing.SwingProgramNodeService;
import com.ur.urcap.api.domain.data.DataModel;
import java.util.Locale;

"""
        + f"public class {c}Service implements SwingProgramNodeService<{c}Contribution, {c}View> {{\n"
        + "    @Override\n    public String getId() {\n"
        + f"        return {jstr(c)}; // saved programs find the node by this: never change it\n    }}\n\n"
        + "    @Override\n    public void configureContribution(ContributionConfiguration configuration) {\n"
        + f"        configuration.setChildrenAllowed({'true' if n.allows_children else 'false'});\n"
        + "        configuration.setUserInsertable(true);\n    }\n\n"
        + f"    @Override\n    public String getTitle(Locale locale) {{\n        return {c}Spec.TITLE;\n    }}\n\n"
        + f"    @Override\n    public {c}View createView(ViewAPIProvider apiProvider) {{\n"
        + f"        return new {c}View(apiProvider);\n    }}\n\n"
        + f"    @Override\n    public {c}Contribution createNode(\n"
        + f"            ProgramAPIProvider apiProvider, {c}View view, DataModel model, CreationContext context) {{\n"
        + f"        return new {c}Contribution(apiProvider, view, model);\n    }}\n}}\n"
    )
    view = (
        java_header(spec, f"program node {n.id!r}: its screen")
        + """
import com.ur.urcap.api.contribution.ViewAPIProvider;
import com.ur.urcap.api.contribution.program.swing.SwingProgramNodeView;
import com.ur.urcap.api.contribution.ContributionProvider;
import java.awt.BorderLayout;
import javax.swing.JPanel;

"""
        + f"public class {c}View implements SwingProgramNodeView<{c}Contribution> {{\n"
        + "    private final ViewAPIProvider api;\n    final Form form;\n\n"
        + f"    {c}View(ViewAPIProvider api) {{\n        this.api = api;\n"
        + f"        this.form = new Form(api, {c}Spec.FIELDS);\n    }}\n\n"
        + "    @Override\n"
        + f"    public void buildUI(JPanel panel, ContributionProvider<{c}Contribution> provider) {{\n"
        + "        panel.setLayout(new BorderLayout());\n"
        + "        JPanel fields = new JPanel();\n"
        + f"        form.build(fields, {c}Spec.TITLE, {c}Spec.DESCRIPTION);\n"
        + "        panel.add(fields, BorderLayout.NORTH);\n"
        + "        JPanel extra = new JPanel();\n"
        + "        panel.add(extra, BorderLayout.CENTER);\n"
        + f"        {c}Hooks.extendUI(extra, api);\n    }}\n}}\n"
    )
    children_write = ""
    if n.allows_children:
        children_write = (
            "        writer.writeChildren();\n"
            f"        for (String line : ScriptTemplate.lines({c}Spec.scriptAfter(v))) {{\n"
            "            writer.appendLine(line);\n        }\n"
        )
    contribution = (
        java_header(spec, f"program node {n.id!r}: its state, title and script")
        + """
import com.ur.urcap.api.contribution.ProgramNodeContribution;
import com.ur.urcap.api.contribution.program.ProgramAPIProvider;
import com.ur.urcap.api.domain.data.DataModel;
import com.ur.urcap.api.domain.script.ScriptWriter;
import com.ur.urcap.api.domain.undoredo.UndoableChanges;
import java.util.Map;

"""
        + f"public class {c}Contribution implements ProgramNodeContribution, Form.Store {{\n"
        + "    private final ProgramAPIProvider api;\n"
        + f"    private final {c}View view;\n"
        + "    private final DataModel model;\n\n"
        + f"    {c}Contribution(ProgramAPIProvider api, {c}View view, DataModel model) {{\n"
        + "        this.api = api;\n        this.view = view;\n        this.model = model;\n    }\n\n"
        + "    @Override\n    public DataModel model() {\n        return model;\n    }\n\n"
        + "    @Override\n    public void change(final Runnable r) {\n"
        + "        api.getProgramAPI().getUndoRedoManager().recordChanges(new UndoableChanges() {\n"
        + "            @Override\n            public void executeChanges() {\n                r.run();\n            }\n"
        + "        });\n    }\n\n"
        + f"    Map<String, ScriptTemplate.Value> values() {{\n        return Form.values(model, {c}Spec.FIELDS);\n    }}\n\n"
        + "    @Override\n    public void openView() {\n        view.form.refresh(this);\n    }\n\n"
        + "    @Override\n    public void closeView() {\n    }\n\n"
        + "    @Override\n    public String getTitle() {\n"
        + f"        if ({c}Spec.LABEL.isEmpty()) {{\n            return {c}Spec.TITLE;\n        }}\n"
        + "        try {\n"
        + f"            return {c}Spec.TITLE + \": \" + ScriptTemplate.render({c}Spec.LABEL, values(), true).trim();\n"
        + "        } catch (RuntimeException e) {\n"
        + f"            return {c}Spec.TITLE;\n        }}\n    }}\n\n"
        + "    @Override\n    public boolean isDefined() {\n"
        + f"        return {c}Spec.problem(values(), Form.problem(model, {c}Spec.FIELDS)) == null;\n    }}\n\n"
        + "    @Override\n    public void generateScript(ScriptWriter writer) {\n"
        + "        Map<String, ScriptTemplate.Value> v = values();\n"
        + f"        for (String line : ScriptTemplate.lines({c}Spec.script(v))) {{\n"
        + "            writer.appendLine(line);\n        }\n"
        + children_write
        + "    }\n}\n"
    )
    return [
        Out(f"ps5/src/{d}/{c}Spec.java", ps5_spec_class(spec, n)),
        Out(f"ps5/src/{d}/{c}Service.java", service),
        Out(f"ps5/src/{d}/{c}View.java", view),
        Out(f"ps5/src/{d}/{c}Contribution.java", contribution),
        Out(f"ps5/src/{d}/{c}Hooks.java", ps5_hooks(spec, n), owned=True),
    ]


