def ps5_hooks(spec: Spec, n: Node) -> str:
    after = ""
    if n.allows_children:
        after = (
            "\n    /** The lines after the children. */\n"
            "    static String scriptAfter(Map<String, ScriptTemplate.Value> values, String rendered) {\n"
            "        return rendered;\n    }\n"
        )
    return (
        f"// Yours: urcapgen created this once and never rewrites it. Keep it in step with\n"
        f"// psx/{spec.psx_archive}/{n.id}.hooks.js — `urcapgen parity` holds both scripts to the same lines.\n"
        f"package {spec.java_package};\n\n"
        "import com.ur.urcap.api.contribution.ViewAPIProvider;\n"
        "import java.util.Map;\nimport javax.swing.JPanel;\n\n"
        f"/** Hand-written behavior of the {n.kind} node {n.id!r} on PolyScope 5. */\n"
        f"final class {n.cls}Hooks {{\n"
        f"    private {n.cls}Hooks() {{\n    }}\n\n"
        "    /** Extra Swing components under the generated form ({@code panel} is empty). */\n"
        "    static void extendUI(JPanel panel, ViewAPIProvider api) {\n    }\n\n"
        "    /** Why the node can't run, beyond the spec's min/max (null: it can). */\n"
        "    static String validate(Map<String, ScriptTemplate.Value> values) {\n        return null;\n    }\n\n"
        "    /** The node's URScript: {@code rendered} is the spec's template filled in. */\n"
        "    static String script(Map<String, ScriptTemplate.Value> values, String rendered) {\n"
        "        return rendered;\n    }\n"
        + after
        + "}\n"
    )


